import bpy, os, json, urllib.parse, urllib.request, math
expected=os.path.normcase(os.path.normpath(r'C:\\mcp-blender\\salvador_lacerda_do_zero.blend'))
if os.path.normcase(os.path.normpath(bpy.data.filepath))!=expected:
    raise RuntimeError(f'ABORTADO arquivo errado {bpy.data.filepath!r}')
BASE='https://geo.salvador.ba.gov.br/arcgis/rest/services/MAPA_BASE/MAPA_BASE_Consulta/MapServer'
# recorte cobrindo todo o terreno Blender atual com pequena margem, em EPSG:31984
ENV={'xmin':552590.0,'ymin':8565430.0,'xmax':553035.0,'ymax':8565900.0,'spatialReference':{'wkid':31984}}
def gj(url,params=None,timeout=30):
    if params: url += ('&' if '?' in url else '?')+urllib.parse.urlencode(params)
    req=urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'})
    with urllib.request.urlopen(req,timeout=timeout) as r: return json.loads(r.read().decode('utf-8','replace'))
for lid in (109,111):
    meta=gj(f'{BASE}/{lid}',{'f':'json'})
    print('LAYER_META',lid,json.dumps({k:meta.get(k) for k in ('name','type','geometryType','description','copyrightText','hasZ','hasM','objectIdField','maxRecordCount','extent','drawingInfo')},ensure_ascii=False,separators=(',',':')))
    print('FIELDS',lid,json.dumps([{k:f.get(k) for k in ('name','alias','type','domain')} for f in meta.get('fields',[])],ensure_ascii=False,separators=(',',':')))
    common={'f':'json','geometry':json.dumps(ENV,separators=(',',':')),'geometryType':'esriGeometryEnvelope','inSR':31984,'spatialRel':'esriSpatialRelIntersects','where':'1=1','outSR':31984}
    cnt=gj(f'{BASE}/{lid}/query',common|{'returnCountOnly':'true'})
    print('COUNT',lid,cnt.get('count'),cnt.get('error'))
    q=gj(f'{BASE}/{lid}/query',common|{'outFields':'*','returnGeometry':'true','resultRecordCount':2000,'returnZ':'true'})
    feats=q.get('features') or []
    print('RETURNED',lid,len(feats),'EXCEEDED',q.get('exceededTransferLimit'),'ERROR',q.get('error'))
    attr_keys={}
    zvals=[]; xypts=0
    for ft in feats:
        a=ft.get('attributes') or {}
        for k,v in a.items():
            if v is not None: attr_keys.setdefault(k,[]).append(v)
        g=ft.get('geometry') or {}
        if 'x' in g and 'y' in g:
            xypts+=1
            if g.get('z') is not None: zvals.append(g.get('z'))
        for path in g.get('paths') or []:
            for p in path:
                xypts+=1
                if len(p)>2 and p[2] is not None: zvals.append(p[2])
    print('GEOM_SUMMARY',lid,'XYPTS',xypts,'ZCOUNT',len(zvals),'ZRANGE',((min(zvals),max(zvals)) if zvals else None))
    # mostra campos numéricos/nominais úteis e amostra compacta
    for k,vals in attr_keys.items():
        kl=k.lower()
        if any(t in kl for t in ('cota','alt','elev','z','nivel','nivel','altura')) or k in ('OBJECTID','FID'):
            uniq=[]
            for v in vals:
                if v not in uniq: uniq.append(v)
                if len(uniq)>=20: break
            print('ATTR_CANDIDATE',lid,k,'SAMPLE',json.dumps(uniq,ensure_ascii=False,default=str))
    for i,ft in enumerate(feats[:8]):
        g=ft.get('geometry') or {}
        gs={}
        if 'x' in g: gs={'x':g.get('x'),'y':g.get('y'),'z':g.get('z')}
        elif g.get('paths'):
            p=g['paths'][0]; gs={'paths':len(g.get('paths') or []),'vertices':sum(len(x) for x in g.get('paths') or []),'first':p[0] if p else None,'last':p[-1] if p else None}
        print('SAMPLE',lid,i,json.dumps({'attributes':ft.get('attributes'),'geometry':gs},ensure_ascii=False,separators=(',',':'),default=str))
